float radius = h; // Assuming particle radius is related to smoothing length h
float minBound = -boxWidth;
float maxBound = boxWidth;

// X-axis boundaries
if (p->x - radius < minBound) {
    p->x = minBound + radius;
    if (p->vx < 0) p->vx = -p->vx * elasticity;
} else if (p->x + radius > maxBound) {
    p->x = maxBound - radius;
    if (p->vx > 0) p->vx = -p->vx * elasticity;
}

// Y-axis boundaries (Ground and Ceiling)
if (p->y - radius < minBound) {
    p->y = minBound + radius;
    if (p->vy < 0) p->vy = -p->vy * elasticity;
} else if (p->y + radius > maxBound) {
    p->y = maxBound - radius;
    if (p->vy > 0) p->vy = -p->vy * elasticity;
}

// Z-axis boundaries
if (p->z - radius < minBound) {
    p->z = minBound + radius;
    if (p->vz < 0) p->vz = -p->vz * elasticity;
} else if (p->z + radius > maxBound) {
    p->z = maxBound - radius;
    if (p->vz > 0) p->vz = -p->vz * elasticity;
}
// END_CODE

